      "text": "第一篇《文史常识》\n第一章 历史常识\n知识点 1 考古文化遗址\n1.河姆渡文化：位于浙江省余姚市，发现了大量人工栽培________的遗迹，\n创造了以榫卯结构为特点的“干栏式建筑”。\n2.仰韶文化：位于河南省仰韶村，分布于黄河上中游地区，被称为“________”。\n代表性遗址包括西安________，是我国最早种植________的文化遗存，出土文物\n有人面鱼纹彩陶盆等。\n3.红山文化：位于内蒙古中南部一带，出土文物有________。\n4.良渚文化：位于浙江省杭州市，是实证________________的关键遗址，最\n大特色是出土的玉器。\n5.大汶口文化：位于山东省泰安市。中晚期出现夫妻合葬，标志着开始或已\n经进入________氏族社会。随葬品数量和质量差异显著，表明社会贫富分化明显，\n私有制已经产生并得到发展。\n6.龙山文化：位于山东省济南市，被称为“________”。\n7.二里头文化：位于河南省洛阳市偃师二里头，学术界一般认为它是夏王朝\n中晚期都城。拥有目前已知我国最早的城市道路系统、宫室建筑群和宫城、最早\n的青铜礼器群、以青铜冶铸作坊和绿松石器制造作坊为代表的最早的官营作坊区\n等诸多重要遗存。二里头遗址是迄今为止可确认的中国最早的王朝都城遗址，开\n中国古代都邑制度之先河，一般将其称为“________________”。\n8.殷墟遗址：位于河南省安阳市，商代后期都城遗址。出土了大量________，\n这是中国最早的系统文字。出土文物中的________，是中国现存最大、最重的青\n铜器。这是中国历史上第一个_______________、并为考古发掘所证实的都城遗址。\n9.三星堆遗址：位于四川省广汉市，是迄今在西南地区发现的范围最大、延\n续 时 间 最 长 、 文 化 内 涵 最 丰 富 的 古 城 、 古 国 、 古 蜀 文 化 遗 址 ， 被 誉 为\n“________________”。出土代表器物有青铜立人像、青铜树、青铜纵目面具等。"
