      "title": "古代战役",
      "text": "知识点 2 古代战役\n1.以少胜多的战役\n牧野之战：周武王伐纣，导致了商朝的灭亡。典故有________。\n________：项羽胜秦军，加速了秦朝的灭亡。典故有破釜沉舟、作壁上观。\n井陉之战：韩信胜赵国，加强了刘邦的实力。典故有________。\n________：曹操胜袁绍，为曹操统一北方奠定基础。典故有夜袭乌巢。\n赤壁之战：孙刘胜曹操，为________局面的形成奠定基础。典故有羽扇纶巾、\n________、万事俱备，只欠东风。\n________：东晋胜前秦，使得汉族中原文化得以延续和发展。典故有投鞭断\n流、风声鹤唳、草木皆兵。\n2.其他重要战役\n________：晋国胜楚国，奠定晋文公霸主地位。典故有退避三舍。\n桂陵之战：齐国胜魏国。典故有________。\n马陵之战：魏伐韩，韩请救于齐。孙膑用“________”诱敌深入，在马陵埋\n伏，导致庞涓自杀、魏主力被歼。\n________：秦国胜赵国，加速了秦国的统一进程。这是中国古代军事史上最\n早、规模最大、最彻底的围歼战。典故有纸上谈兵。\n邯郸之战：赵国与诸国合纵对付秦国，大败秦军。典故有________。\n知识点 3 古代政治制度\n1.秦朝：在中央设置三公九卿制。“三公”是指在中央设________（“百官\n之长”，帮助皇帝处理全国的政事）、________（主管军事）、________（执掌\n群臣奏章，下达皇帝召令，兼理国家监察事务）三个最高官职。地方上，秦朝实\n行郡县制。\n2. 汉 朝 ： 西 汉 初 期 ， 地 方 上 实 行 郡 国 并 行 制 。 汉 武 帝 时 期 ， 正 式 颁 布\n“________”，削弱诸侯势力，进一步增加中央集权。\n3.隋唐：在中央实行三省六部制。唐朝“三省”是指________（负责草拟和\n颁布皇帝诏令）、门下省（负责________）、________（负责执行国家的政令）。\n________下设吏、户、礼、兵、刑、工六部。\n4.宋朝：中央设枢密使、________、三司使，分割宰相的军权、行政权、财\n政权。\n5.元朝：中央设立________作为中央最高的行政机构。地方设行中书省，简\n称“行省”。元朝的行省制是________的开端。"
