      "title": "古代选官制度",
      "text": "（4）影响：中国古代存在时间最长、影响最深远的选官制度。\n二、科举考试程序（明清时期）\n明清两朝科举的基本制度和考试程序大体是一致的，其中以进士科考试最为\n重要。进士科正式考试共分童试、乡试、会试和殿试。\n童试：包括县试、童试、院试三级，通过院试者称为“生员”，俗称“________”。\n乡试：又称“秋闱”。考中者为“________”，第一名称“________”。\n会试：又称“礼闱”“春闱”。取中者为“________”，第一名称“________”。\n殿试：一般由皇帝亲自主持，前三名分别为“________、榜眼、探花”。\n【知识延伸】\n连中三元\n考生在科举考试中身兼乡试第一，会试第一，殿试第一，即________________。\n知识点 5 古代赋税制度\n1.初税亩：春秋时期，________率先实行，按照拥有土地数量的多少征收赋\n税。这是中国征收土地税的开端。\n2.租庸调制：始于________，唐朝前期趋于完善。租是田租；调是________；\n庸是纳绢代役。\n3.两税法：________后期，改革赋税制度，实施两税法。两税法将各种名目\n的赋税统一并到________________中；每户按资产交纳户税，按田亩交纳地税；\n分为________两季征收。两税法改变了以往“以人丁为主”的征税标准，转向“以\n财产、土地为核心”。\n4.一条鞭法：________时期，由张居正主持改革。把各州县的田赋、徭役以\n及其他杂征总为一条，合并征收银两，按亩折算缴纳，推动________向________\n转变，适应了商品经济的发展趋势。\n5.摊丁入亩：________时期，雍正初年开始实行摊丁入亩，即把丁银全部摊\n入地亩中征收。摊丁入亩的实行标志着延续了数千年的________的废除。\n知识点 6 古代变法与改革\n1.管仲改革：春秋时期，________任用管仲进行改革。主要内容有“叁其国\n而伍其鄙”“________________”等。改革促使齐国迅速富强，齐桓公成为春秋\n首霸。"
