      "text": "2.李悝变法：________初期，魏文侯为了增强国力，任用李悝为相，在诸侯\n国中率先推行变法。主要内容有打破贵族世袭的“世卿世禄制”，主张选贤任能；\n推行“尽地力之教”；实施“________”；编撰________（中国历史上第一部系\n统的成文法典）。这是中国历史上第一次比较系统的地主阶级改革。\n3.商鞅变法：________时期，秦孝公任用商鞅进行两次变法。主要内容有废\n井田，开阡陌，确立________________；重农抑商，奖励耕织；奖励军功，按功\n授爵；推行“分户令”（“分异令”）；户籍什伍制、连坐法；推行县制。变法\n为秦统一六国奠定了基础。\n4.北魏孝文帝改革：南北朝时期，北魏孝文帝在位时推行改革。主要内容有\n颁布均田令；迁都________；推行________，说汉话、改汉姓、通汉婚等。改革\n促进了北方民族融合，是中国古代史上最成功、影响最深远的少数民族汉化改革。\n5.王安石变法：________时期，宋神宗任用王安石进行变法，旨在富国强兵。\n主要内容有“富国”方面的________、募役法（免役法）、________________、\n方田均税法；“强兵”部分的________、保马法、将兵法等。\n6.张居正改革：明神宗万历年间，张居正进行整顿改革。政治上推行“考成\n法”。经济上推行“一条鞭法”，这是其变法的核心内容。\n知识点 7 古代边疆治理\n1.西藏\n（1）元朝：设置________，专门管理全国佛教事务和________地区的行政事\n务。________自此开始成为中国领土不可分割的一部分。\n（2）清朝\n崇德年间，设立理藩院为管理蒙古、回部及西藏等少数民族的最高中央机构。\n雍正年间，设置________，和达赖、班禅共同管理西藏。\n2.新疆\n（1）西汉：汉宣帝设________________，这是今新疆地区正式归属中央统辖\n的开始。\n（2）唐朝\n________设立安西都护府，主管西域（今新疆和中亚地区）事务。\n武则天设立________________，管辖天山以北包括阿尔泰山和巴尔喀什湖以\n西的广大地区。\n（3）清朝\n乾隆年间，设置________，管辖包括巴尔喀什湖在内的整个新疆地区。"
