      "text": "工程。\n（2）战国时期：秦国李冰主持修建的________、韩国水工郑国修建的________。\n【知识延伸】\n都江堰\n1.三大主体工程\n鱼嘴分水堤：形如鱼头的堤坝将岷江一分为二，形成内江和外江。它利用地\n形和水势，实现了“四六分水”的动态平衡：枯水期，约六成江水流入________，\n保证灌溉；洪水期，约六成江水排入________，实现泄洪。\n飞沙堰溢洪道：作为内江的“安全阀”，当水量过大时，多余的水会漫过这\n道低矮的堰坝，排入外江。更重要的是，它利用水流在弯道产生的离心力，形成\n漩涡，能将内江 80%以上的泥沙和卵石“甩”出，有效防止了渠道淤积。\n宝瓶口引水口：人工在玉垒山凿开的一个形似瓶口的狭窄通道，是内江水进\n入成都平原的咽喉。它像一道天然闸门，精确控制进入灌区的水量，确保平原地\n区用水平稳。\n2.历史地位\n都江堰是世界现存年代最久、唯一留存、________的无坝引水水利工程。2000\n年列入世界文化遗产，2018 年列入世界灌溉工程遗产名录。\n（3）秦朝时期：修建灵渠，联接________两大水系，促使秦始皇统一岭南。\n（4）隋唐时期：________时期，吴王夫差开凿了连接长江与淮河的邗沟，这\n是有确切纪年的中国大运河最早的河段。隋朝时期，为加强都城洛阳与南方的联\n系 ， 隋 炀 帝 下 令 大 规 模 开 凿 运 河 。 元 朝 时 期 ， 为 缩 短 航 程 ， 对 运 河 进 行 了\n“________”，先后开凿了济州河、会通河、通惠河等新河道，使运河不再绕道洛\n阳。\n知识点 10 近代不平等条约\n时期 不平等条约 内容 影响\n鸦片战争\n（1840-1842） 《南京条约》\n（1）割让________给英国。\n（2）赔款 2100 万银元。\n（3）开放广州、厦门、福州、宁\n波、________为通商口岸。\n（4）中英“协定关税”。\n中 国 近 代 第 一\n个不平等条约。\n中 国 ________\n沦 为 半 殖 民 地\n半封建社会。\n第二次\n鸦片战争 《________》（1）外国公使进驻北京。\n（2）外国传教士可到内地传教。\n使 中 国 丧 失 了\n大 片 的 领 土 和"
