      "text": "【知识延伸】\n洋务运动——创办军事工业\n曾国藩：在安徽创办________________（我国第一个近代军工厂）。\n李鸿章：在上海创办________________（当时国内最大的兵工厂）。\n左宗棠：在福州创办福州船政局。\n张之洞：在武汉创办汉阳铁厂（中国近代最早的官办钢铁企业）。\n3.戊戌变法\n1895 年，康有为、梁启超等组织公车上书，揭开了戊戌变法的序幕。\n1898 年，________皇帝开始变法，持续 103 天，史称戊戌变法，又称百日维\n新。1898 年 9 月 21 日，慈禧太后发动“戊戌政变”标志着“戊戌变法”失败。\n戊戌变法中，设立________________，这是中国近代第一所国立大学，标志\n着中国近代国立高等教育的开端。\n4.辛亥革命\n1894 年，孙中山在檀香山成立兴中会，这是中国第一个资产阶级________。\n1905 年，孙中山在东京成立中国________。这是中国第一个资产阶级革命政\n党，以“驱除鞑虏，恢复中华，创立民国，平均地权”为纲领。该纲领后又被解\n释为三民主义，即民族、民权、民生，其中________是核心。\n1911 年 10 月 10 日，________爆发，标志着辛亥革命开始。\n1912 年 1 月 1 日，中华民国成立，定都________，以 1912 年为民国元年。\n1912 年 3 月，《________________》颁布，中国历史上第一部具有资产阶级\n共和国宪法性质的重要文件。\n辛亥革命推翻了清王朝的统治，结束了中国两千多年的封建________制度，\n使民主共和的观念深入人心，但是________中国半殖民地半封建社会的性质。\n知识点 12 党的诞生和国民大革命\n中共一大：1921 年 7 月 23 日，中共一大在________（后转移至浙江嘉兴南\n湖）召开。会议确定党的名称为“中国共产党”，通过了党的第一个________，\n选举陈独秀为中央局书记。党的一大的召开标志着中国共产党的成立。\n【知识延伸】\n中国共产党早期组织\n1920 年 8 月，________在上海成立了中国第一个共产党早期组织，随后创办\n中国共产党历史上第一个党刊——《________》。"
