      "text": "席。这是中国共产党领导建立的第一个全国性红色政权。\n红军长征：王明等人的________________错误，使红军在第五次反“围剿”\n中遭到失败，被迫开始长征。1934 年 10 月 10 日，红军从江西省瑞金、古城等地\n出发。1936 年 10 月 9 日，红四方面军指挥部到达________，同红一方面军会师；\n10 月 22 日，红二方面军指挥部到达甘肃隆德将台堡（今属宁夏回族自治区），\n同红一方面军胜利会师。红军三大主力会师，宣告红军二万五千里长征胜利结束。\n遵义会议：1935 年 1 月，在贵州遵义召开中共中央政治局扩大会议。会议结\n束了“左”倾教条主义在军事上的错误指挥，会后成立了由毛泽东、________、\n________组成的三人军事领导小组，事实上确立了________在党中央和红军的领\n导地位。遵义会议是党的历史上一个生死攸关的转折点，是中国共产党第一次自\n主地运用马克思列宁主义基本原理解决中国革命的问题，标志着中国共产党在政\n治上________________。\n知识点 14 抗日战争\n1.日本侵华战争的开始\n________________：1931 年 9 月 18 日，日本炸毁柳条湖铁路，炮轰北大营。\n这是中国抗日战争的起点，揭开了世界反法西斯战争的序幕。\n________：1937 年 7 月 7 日，日军挑起卢沟桥事变。这是中国全民族抗战的\n开端，开辟了世界反法西斯战争的东方主战场。\n2.抗日民族统一战线的建立\n________________：1935 年底召开，通过了《中央关于目前政治形势与党的\n任务决议》，确定了建立抗日民族统一战线的方针。\n西安事变：1936 年 12 月 12 日，张学良、杨虎城逼蒋抗日，又称双十二事变。\n西安事变的和平解决，标志着十年内战基本结束，抗日民族统一战线________。\n洛 川 会 议 ： 1937 年 洛 川 会 议 通 过 《 抗 日 救 国 十 大 纲 领 》 ， 制 定\n________________。\n《中共中央为公布国共合作宣言》：1937 年 9 月，国民党发表《中共中央为\n公布国共合作宣言》，标志着第二次国共合作开始，抗日民族统一战线________。\n3.正面战场与敌后战场\n________：1937 年 8 月至 11 月，是抗战初期规模最大、战斗最惨烈的战役，\n粉碎了日本“三个月灭亡中国”的狂妄计划。\n平型关大捷（属于太原会战）：1937 年 9 月，林彪率领八路军 115 师取得平\n型关大捷。这是全民族抗战以来中国军队主动对日作战取得的第一个重大胜利，"
