      "text": "包括________、________、平津战役三场战略性战役。\n【知识延伸】\n________\n1948 年 11 月—1949 年 1 月。被称为是“小推车推出来的胜利”，是三大战\n役中解放军牺牲最重、歼敌数量最多、政治影响最大、战争样式最复杂的战役。\n5.七届二中全会\n1949 年 3 月，党的七届二中全会在河北省西柏坡召开。会议讨论和决定的主\n要问题有：一是确定了彻底推翻国民党统治，夺取全国的方针；二是指出工作重\n心应从________转向________，并以生产建设为中心；三是阐述了在全国胜利后\n仍会存在两种基本矛盾，一种是________________________的矛盾，一种是中国\n人民和帝国主义的矛盾。同时告诫全党在革命胜利后要警惕资产阶级“糖衣炮弹”\n的袭击，务必继续地保持谦虚、谨慎、不骄、不躁和________的作风。\n6.渡江战役\n1949 年 4 月 21 日，中国人民解放军强渡长江。4 月 23 日，解放军占领________，\n统治中国 22 年的国民政府覆灭。"
