      "group": "history",
      "title": "先秦诗歌",
      "text": "第二章 文学常识\n知识点 1 先秦诗歌\n1.《诗经》\n《诗经》，又称《诗》或《诗三百》，共收入自________初期至春秋中叶约\n500 年间的诗歌 305 篇。《诗经》是我国第一部________，开创了中国诗歌________\n的源头。\n【知识延伸】\n《诗经》六义\n《诗经》分风、雅、颂三部分，大量运用了赋、比、兴表现手法。“风、雅、\n颂”与“赋、比、兴”合称“六义”。\n________——周代各地的歌谣，大部分是黄河流域的民间乐歌。常见名篇有\n《关雎》、《硕鼠》、《蒹葭》、《桃夭》等。\n雅——周人的正声雅乐，分小雅、大雅。常见名篇有《鹿鸣》、《采薇》等。\n颂——周王庭和贵族宗庙________的乐歌，又分为周颂、鲁颂、商颂。常见\n名篇有《清庙》等。\n________——铺陈直叙，即诗人把思想感情及其有关的事物平铺直叙地表达\n出来。\n比——比方，以彼物比此物，借一个事物来作比喻。\n________——触物兴词，客观事物触发了诗人的情感，大多在诗歌的开端。\n2.《楚辞》\n西汉末年，刘向辑录屈原、宋玉等人辞赋，编成《楚辞》。《楚辞》是我国\n第一部________诗歌总集。\n屈原，我国浪漫主义文学的奠基人、________，其作品主要有《离骚》《天\n问》《招魂》《九歌》《怀沙》《哀郢》等。\n《________》，是我国第一首长篇政治抒情诗。\n《诗经·________》和《楚辞·________》并称为“风骚”。\n知识点 2 魏晋诗歌\n1.三曹\n曹操：字孟德，开创建安之风，代表作品《短歌行》《观沧海》《龟虽寿》。"
