      "group": "history",
      "title": "魏晋诗歌",
      "text": "曹丕：字子桓，《________》是现存最早的完整的七言诗。著有《________》，\n这是中国文学史上第一部有系统的文学批评专论。\n曹植：字子建，作品有《洛神赋》《七步诗》等，谢灵运赞其“________”。\n【知识延伸】\n经典名句\n《观沧海》：日月之行，若出其中；星汉灿烂，若出其里。\n《龟虽寿》：老骥伏枥，志在千里；烈士暮年，壮心不已。\n《燕歌行》：秋风萧瑟天气凉，草木摇落露为霜。\n《洛神赋》：翩若惊鸿，婉若游龙，荣曜秋菊，华茂春松。\n2.陶谢\n陶渊明：字元亮，别号________，东晋人，我国第一位________，被称为\n“________________________”。代表作有《饮酒》《归园田居》《桃花源记》《归\n去来兮辞》等。\n谢灵运：东晋人，诗歌史上自觉以________入诗的第一人。\n【知识延伸】\n经典名句\n《饮酒·其五》：采菊东篱下，悠然见南山。\n《归园田居》：种豆南山下，草盛豆苗稀。\n《归去来兮辞》：悟已往之不谏，知来者之可追。\n知识点 3 唐宋八大家\n1.唐宋八大家：主持唐宋古文运动的中心人物，包括唐二家（______________）\n和宋六家（苏轼、苏洵、苏辙、欧阳修、曾巩、王安石）。\n【知识延伸】\n古文运动\n古文运动是唐宋时期提倡古文、反对骈文的文体改革运动。其核心是反对六\n朝以来形式僵化、内容空洞的骈文，提倡恢复先秦两汉时期质朴自由、言之有物\n的散文传统，以复兴________，挽救时局。\n2.韩愈：世称韩昌黎、________。代表作有《________》《祭十二郎文》《马\n说》《杂说》《进学解》等。在古文运动中提出“文以载道”的核心主张。被誉"
