      "group": "history",
      "title": "唐宋八大家",
      "text": "为唐宋八大家之首，苏轼称韩愈“文起八代之衰”。与柳宗元并称“韩柳”。\n3.柳宗元：世称柳河东、________、柳柳州。代表作有《永州八记》《捕蛇\n者说》《黔之驴》等，是我国第一位把________正式写成独立的文学作品的作家。\n4.欧阳修：号醉翁，晚年号“________”。代表作有《醉翁亭记》《卖油翁》。\n5.王安石：号半山，世称王荆公、王临川。代表作有《伤仲永》《游褒禅山\n记》等。列宁称其为“________中国最伟大的改革家”。\n【知识延伸】\n经典名句\n《师说》：闻道有先后，术业有专攻，如是而已。\n《醉翁亭记》：醉翁之意不在酒，在乎山水之间也。\n《游褒禅山记》：世之奇伟、瑰怪，非常之观，常在于险远，而人之所罕至焉，\n故非有志者不能至也。\n知识点 4 唐诗\n1.初唐诗歌\n“初唐四杰”是初唐文学家王勃、杨炯、卢照邻、________的并称，其中________\n被称为四杰之首，人称“诗杰”。\n【知识延伸】\n王勃的经典名句\n《送杜少府之任蜀州》：海内存知己，天涯若比邻。\n《滕王阁序》：落霞与孤鹜齐飞，秋水共长天一色。\n2.盛唐诗歌\n________：人称“________”。代表作有《使至塞上》《送元二使安西》《九\n月九日忆山东兄弟》等。苏轼曾说“味摩诘之诗，诗中有画；观摩诘之画，画中\n有诗”。\n李白：号________，人称“谪仙人”“________”，唐代浪漫主义诗人。代\n表作有《蜀道难》《将进酒》等。\n杜甫：自号少陵野老，人称“________”，唐代现实主义诗人。代表作有“三\n吏”“三别”以及《望岳》《闻官军收河南河北》等。其诗歌被后人评价为“________”。"
