      "text": "苏轼\n《念奴娇·赤壁怀古》 大江东去，浪淘尽，千古风流人物。\n《水调歌头·明月几时有》 但愿人长久，千里共婵娟。\n《和董传留别》 粗缯大布裹生涯，腹有诗书气自华。\n辛弃疾\n《永遇乐·京口北固亭怀古》 想当年，金戈铁马，气吞万里如虎。\n《破阵子·为陈同甫赋壮词以寄之》 醉里挑灯看剑，梦回吹角连营。\n（2）婉约派\n人物 代表作品 名句\n李清照\n《夏日绝句》 生当作人杰，死亦为鬼雄。\n《醉花阴·薄雾浓云愁永昼》 东篱把酒黄昏后，有暗香盈袖。\n柳永\n《蝶恋花·伫倚危楼风细细》 衣带渐宽终不悔，为伊消得人憔悴。\n《雨霖铃·秋别》 今宵酒醒何处？杨柳岸，晓风残月。\n秦观 《鹊桥仙》 两情若是久长时，又岂在朝朝暮暮。\n知识点 6 元曲\n1.元曲\n元曲四大家：________、白朴、________、马致远\n________：被誉为“曲圣”，代表作有《窦娥冤》《拜月亭》《单刀会》等。\n郑光祖：代表作有《________》等。\n________：代表作有《梧桐雨》《墙头马上》等。\n马致远：有“________”之称。代表作有杂剧《汉宫秋》，小令《天净沙·秋\n思》被誉为“________”。\n王实甫：代表作有《________》，首次正面提出“愿普天下有情人都成眷属”\n的美好愿望。\n元曲四大悲剧：《________》《汉宫秋》《________》《赵氏孤儿》。\n2.明清戏曲\n________：明代戏曲家，被称为“东方的莎士比亚”。代表作有“临川四梦”，\n包括《牡丹亭》（《还魂记》）《紫钗记》《南柯记》《邯郸记》。\n洪昇：清代戏曲家，代表作《________》。\n孔尚任：清代戏曲家，代表作《________》，被誉为“借离合之情，写兴亡\n之感”。\n清代“戏曲双璧”：《________》、《________》"
