      "title": "古代小说",
      "text": "知识点 7 古代小说\n1.小说的雏形\n《搜神记》：东晋时期，干宝所作笔记体志怪小说集，开创了我国古代神话小\n说的先河。\n《________》：南朝宋时期，刘义庆组织编写，是我国最早的一部文言志人小\n说集。\n2.四大奇书与四大名著\n明代四大奇书\n《水浒传》《三国演义》《西游记》\n《________》\n古代四大名著 《________》\n《________》：作者为元末明初作家施耐庵，是中国历史上第一部用古白话文\n写成的歌颂农民起义的长篇章回体小说。\n《________》：作者为元末明初作家罗贯中，我国第一部长篇历史小说，章回\n体小说的开山之作。\n《________》：作者为明代作家吴承恩，属于浪漫主义神话小说，开辟了神魔\n长篇章回小说的新门类。鲁迅评价其“神魔皆有人情，精魅亦通世故”。\n《金瓶梅》：作者署名兰陵笑笑生。中国明代长篇白话世情小说，中国第一部\n________________的章回体长篇小说，小说“寄意于时俗”，被誉为“四大奇书\n之首”。\n《红楼梦》：作者清代曹雪芹，原名《________》《风月宝鉴》《金陵十二钗》\n等，成书于乾隆年间，被誉为“封建社会的百科全书”，中国最具文学成就的古\n典小说及章回小说的________。《红楼梦》第一回中写到“满纸荒唐言，一把辛\n酸泪。都云作者痴，谁解其中味？”“字字看来皆是血，________不寻常”出自\n曹雪芹的《回前诗》，是曹雪芹自己对《红楼梦》的评说。\n3.其他明清小说\n《________》：又名《鬼狐传》，作者清代________，中国古典文言短篇小说\n之巅峰。老舍评价“鬼狐有性格，笑骂成文章”，郭沫若评价“写鬼写妖高人一\n等，刺贪刺虐入木三分”。\n《________》：作者清代吴敬梓，我国文学史上杰出的现实主义的章回体长篇\n讽刺小说。《________》是其中的著名篇章。\n知识点 8 史学著作\n体裁 著作 作者 地位\n编年体 《________》 孔子 第一部编年体史书\n《________》 左丘明 第一部叙事详细的编年体史书"
