      "text": "《________》：明末清初宋应星所著，被誉为“17 世纪中国工艺百科全书”。\n3.天文历法\n（1）中国古代天文历法成就\n《太初历》：________时，制定出中国第一部较完整的历书《太初历》，开始\n以________为岁首，正式把________________定于历法。\n《大明历》：南北朝时期________创制，首次引入了“________”的概念。\n《大衍历》：唐朝僧一行制订，是用科学方法实测地球________长度的创始人。\n《授时历》：元朝________主持全国范围的天文测量，编《授时历》。\n（2）天干地支\n干支纪年法萌芽于西汉初年，通行于东汉以后，是我国古代一直沿用的纪年法。\n天干：甲、乙、丙、丁、戊、己、庚、辛、壬、癸。\n地支：子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥。\n【知识延伸】\n干支纪年法的计算\n1.计算天干\n公式：（年份-3）÷10，取余数。\n对应：余数是几，就对应天干的第几位。若余数为 0，则对应第 10 位“癸”。\n2.计算地支\n公式：（年份-3）÷12，取余数。\n对应：余数是几，就对应地支的第几位。若余数为 0，则对应第 12 位“亥”。\n知识点 3 古代医学\n1.中国古代著名医药学家\n扁鹊：战国时期，发明了________四诊法，著有《________》，被称为“________”\n“医祖”。\n华佗：东汉末年，发明________，创编了五禽戏（模仿________________），\n被誉为“外科鼻祖”“外科圣手”。\n张仲景：东汉末年，著有《________________》，确立了中医“辨证论治”\n的基本原则，被称为“________”。\n孙思邈：唐朝时期，著有《________》，首次主张妇、儿疾病单独设科，被\n称为“________”。\n________：南宋时期，著有《洗冤集录》，开创了“法医鉴定学”，被称为\n“世界法医学鼻祖”。"
