      "text": "【知识延伸】\n建筑元素\n1.华表：古代宫殿、陵墓等大型建筑物前面做装饰用的巨大石柱。\n2.牌楼：用于表彰、纪念、装饰、标识和导向的一种建筑物，而且又多建于\n宫苑、寺观、陵墓、祠堂、衙署和街道路口等地方。\n3.水榭：建于水边或水上的亭台，以供游客休息、观赏风景的中国传统式建筑。\n4.影壁：也称作照壁，是古代寺庙、宫殿、官府衙门和深宅大院前的一种建\n筑，即门外正对大门以作屏障的墙壁。\n5.城阙：城门两旁的瞭望阁楼。\n知识点 6 汉字与书法\n1.汉字\n起源传说：仓颉造字，被称为“造字圣人”。\n汉字六书：清代以后一般指________、指事、会意、________、转注、假借。\n汉字七体：________、金文、小篆、________、草书、楷书、行书。\n2.书法家及书法作品\n________：东晋书法家，被称为“________”，其书法“飘若浮云，矫若惊\n龙”，代表作有《兰亭序》《黄庭经》《快雪时晴帖》等。\n楷书四家：唐朝________、唐朝颜真卿、唐朝柳公权、元朝________。\n颜筋柳骨：颜真卿的书法和柳公权的书法。\n颠张醉素：唐朝“草圣”张旭与怀素和尚的并称，张旭的代表作是《古诗四\n帖》，怀素的代表作是《________》。\n宋四家：北宋时期四位书法家________、________、米芾、蔡襄的合称。\n行书代表作：王羲之的“天下第一行书”《________》，颜真卿的“天下第\n二行书”《________》，苏轼的“天下第三行书”《________》。\n知识点 7 古代绘画\n一、著名画家及作品\n1.________：东晋画家，率先提出“以形写神”的绘画理论，被誉为“才绝、"
