      "page": 94,
      "printedPage": 85,
      "group": "science",
      "title": "医学检查",
      "text": "辅助诊断。\n②________（CEA）：一种广谱标志物，在消化道肿瘤（如结直肠癌、胃癌）\n和肺腺癌中可能升高。\n③糖类抗原 19-9（CA19-9）：主要用于________、胆管癌的辅助诊断和监测，\n在胃癌、结直肠癌中也可能升高。\n④糖类抗原 125（CA125）：常用于________的辅助诊断和疗效监测。\n（4）幽门螺杆菌\n幽门螺杆菌是________能在人胃内强酸环境中长期、稳定定植的细菌。主要\n传播途径为“口-口”和“粪-口”。\n常见检测方法：\n①¹³C/¹⁴C尿素呼气试验：这是________诊断和根除后________的“金标准”。\n检查前________空腹。\n②血清Hp抗体检测：仅表明曾经感染，________区分是“现症感染”还是“既\n往感染”。不能用于诊断和复查。检查前________空腹。\n2.影像学检查\n（1）X光\n适用：肺部疾病（如肺炎、肺结核）和________的初步筛查。\n特点：影像重叠，微小病灶易漏诊；软组织分辨力差；有少量________。\n（2）CT（电子计算机断层扫描）\n适用：急诊中脑出血、外伤、胸痛的首选，肺结节、早期肺癌、实质性脏器\n（肝、胆、胰、肾）的肿瘤或结石筛查。\n特点：对软组织（如脊髓、韧带）的分辨力不如核磁共振。有________，辐\n射剂量高于X光。\n（3）MRI（核磁共振）\n适用：脑梗死（特别是早期）、脑肿瘤等神经系统疾病以及肿瘤分期筛查。\n特点：检查时间长，噪音大，体内有________植入物通常不能做。________\n电离辐射。\n（4）超声（B超）\n适用：肝囊肿、胆囊结石、脂肪肝等，胎儿检查、心脏结构、甲状腺、乳腺\n结节等筛查。\n特点：无法看清肺部、肠道、骨骼等问题，受操作者经验影响比较大。________\n电离辐射。"
