      "title": "灾害应对",
      "text": "二氧化碳灭火器 ________灭火器 ________灭火器\n灭火剂 液态二氧化碳 硫酸铝、碳酸氢钠 有灭火效能的无机盐\n适用火灾\n________、贵重设\n备、精密仪器、电\n气设备及油类的初\n起火灾\n木材等固体物质或\n汽油、柴油等液体\n火灾\n可燃固体、液体、气\n体及带电设备的初起\n火灾\n不适用火灾 ________火灾\n水溶性可燃液体、\n________、忌水物\n质和精密仪器火灾\n________燃烧火灾\n2.雷电\n若处室外，应寻找低洼处（如土坑）藏身，低头曲身下蹲，同时双手抱膝，\n两脚________。远离导电物品（如金属广告牌或湿润树干）和电力设施（如灯杆、\n电线杆），不要拿着金属物品（如带有金属杆的雨伞）在雷雨中停留。\n若处室内，________拨打接听电话，拔掉电器用具插头；不开门开窗以防雷\n电直击室内。\n3.洪水\n若时间充裕，应按照预定路线，有组织地向________、高地等处转移；来不\n及转移时，应立即爬上屋顶、大树、高墙等高的地方，做暂时避险，等待援救。\n4.泥石流\n发生泥石流时，要立即向坚固的高地或与泥石流成________方向的两侧山坡\n跑，离开沟道、河谷地带。\n5.地震\n若身处低矮楼层，应尽快疏散到屋外开阔空地，远离人多的地方、高层建筑\n和桥梁。若身处高层，应躲在低矮牢固的家具（如床、桌）下或________、刚度\n强的小开间的室内（如厨房、卫生间、承重墙墙角等）暂避，并用手护住头部。\n【知识延伸】\n地震\n1.地震的类型及分布\n地震按其成因一般分为________、火山地震、塌陷地震。\n世界有三大地震带，即________地震带（世界上最大的地震带）、欧亚地震带、\n海岭地震带。其中环太平洋地震带主要影响我国东部地区，欧亚地震带主要影响我国\n西南地区，海岭地震带不影响我国。\n2.地震的相关名词\n（1）震源：地球内部岩层破裂引起震动的地方。\n（2）震中：地面正对着震源的那一点。"
