      "group": "science",
      "title": "灾害应对",
      "text": "（3）震级：衡量地震本身大小，代表地震释放能量的多少。一次地震，________\n震级。我国目前使用的震级标准是里氏分级表，共分 9 个等级，震级相差一级，\n地震所释放的能量相差________倍。\n（4）烈度：衡量地震对地表及建筑物的影响和破坏程度。一次地震，可以有\n________烈度。一般来说，震级越大，烈度________。\n（5）地震波\n纵波（P波）：振动方向与传播方向一致。会引起地面上下颠簸，破坏力相对\n较弱。传播速度________，穿透力最强，可以在固体、液体和气体中传播。\n横波（S波）：振动方向与传播方向垂直。会引起地面水平摇晃，对建筑物的\n剪切破坏力强。传播速度较慢，只能在_______中传播，不能在液体和气体中传播。"
