      "text": "第三章 高新技术\n知识点 1 计算机技术\n1.基础知识\n（1）系统构成\n①硬件系统\n运算器：进行运算的部件，计算机中的数值运算采用________。\n控制器：与运算器合称________________（CPU）。\n存储器：分为内存储器与外存储器，简称内存与外存。内存储器比外存储器\n容量小，价格昂贵，但存取速度快。\n【知识延伸】\n存储器\n只读存储器（ROM）：只能读出，一般不能写入，断电数据________丢失。\n随机存储器（RAM）：可以读出，也可以写入，断电数据________丢失。\n输入设备：把人的意图传达给机器的一种联系人和机器的部分。键盘、鼠标、\n摄像头、扫描仪、光笔、手写输入板、游戏杆、语音输入装置等都属于输入设备。\n输出设备：把机器的工作情况和计算结果报告给有关人员的一种联系机器和\n人的部分。显示器、打印机、绘图仪、影像输出系统、语音输出系统等都属于输\n出设备。\n②软件系统\n系统软件：控制、协调计算机及外部设备，支持应用软件开发和运行的软件，\n包括操作系统、语言处理系统、数据库管理系统、系统辅助处理程序。\n应用软件：为解决各类实际问题而设计的程序软件，如办公软件、互联网软\n件、多媒体软件等。\n（2）常见概念\n①字节\n字节（Byte）是计算机用于计量存储容量的________。\n二进制位（bit）是计算机用于计量存储容量的最小单位。\n1B（byte，字节）=8bit（比特）；1KB=1024B；1MB（兆）=1024KB；1GB=1024MB；\n１TB＝1024GB；1PB=1024TB；1 个汉字＝2B。\n②快捷键\n复制——Ctrl+C 粘贴——Ctrl+V 剪切——________\n全选——Ctrl+A 撤销——________ 保存——Ctrl+S"
