      "text": "模开发利用，储量越来越少，总有枯竭一天的能源，如化石能源、________、油\n页岩等。\n2.当前主要的能源\n（1）核能\n核能是原子核结构发生变化时所释放出的能量，是目前唯一现实的、可大规\n模代替________的能源，包括裂变能和聚变能。\n核裂变：主要用于核电站发电，主要燃料是________。\n核聚变：目前人类已实现不受控制的核聚变，如________的爆炸，但尚不能\n将能量控制和有效利用。\n【知识延伸】\n核能发展\n1942 年，________在芝加哥大学运行世界上第一座可控原子核裂变链式反应\n堆。原子能、半导体、计算机、激光器并称 20 世纪的四大发明。\n1954 年，________建成世界上第一座核电站奥布灵斯克核电站。\n1991 年，中国大陆第一座核电站________核电站建成。\n1994 年，中国大陆第一座大型商用核电站________核电站建成。\n2021 年，全球第一台“华龙一号”核电机组福建福清核电 5 号机组投入商业\n运行。\n2025 年 1 月 20 日，我国有“人造太阳”之称的全超导托卡马克________实验\n装置（EAST）首次完成 1 亿摄氏度 1000 秒“高质量燃烧”，标志我国聚变能源\n研究实现从基础科学向工程实践的重大跨越。\n（2）太阳能\n间接利用：利用燃料、风力、水力、海洋热能等各种被固定的太阳辐射能中\n的能量。\n直接利用：直接利用太阳辐射的能量。\n（3）风能\n开发风能，主要是利用风力发电。\n（4）生物质能\n生物质能是太阳能以化学能形式贮存在生物质中的能量形式，即以生物质为\n载体的能量，如沼气（主要成分为甲烷）。生物质能是唯一一种可再生的________，\n也是人类历史上________的能源。\n（5）可燃冰\n可燃冰（________水合物）是分布于深海沉积物或陆域的永久冻土中，由天"
