      "text": "然气与水在高压低温条件下形成的类冰状的结晶物质，主要成分是________，储\n量丰富。\n知识点 3 生物工程技术\n1.基因工程\n含义：又称DNA重组技术，是通过对生物体的遗传物质进行体外“剪切、拼\n接和重组”，从而定向改造生物性状或创造新物种的技术。它是生物工程技术的\n________。\n应用：转基因作物，如________、抗倒伏水稻、转基因食品；基因治疗，如\n人工合成胰岛素、________等。\n2.细胞工程\n含义：通过细胞培养、融合、核移植、基因导入等技术，改良生物特性或获\n得特定产物的技术。\n应用：包括________技术、干细胞技术、体细胞杂交技术（如用番茄和马铃\n薯培育成“番茄—马铃薯”）等。\n3.发酵工程\n含义：也称微生物工程，是________________、应用最广泛的生物技术。\n应用：酒（________发酵）、醋（醋酸菌发酵）、酸奶（________发酵）、\n泡菜（________发酵）、酱油（米曲霉菌发酵）、面包（________发酵）、腐乳\n（毛霉菌发酵）、味精等都是发酵的产物。\n4.酶工程\n含义：利用酶的________作用，对酶进行改造、生产、固定化，并将其应用\n于工业生产、食品加工、医药、环保等领域的技术。\n应用：在食品加工、轻化工业、医药上应用广泛，如葡萄糖浆的生产，加酶\n洗衣粉，诊断试剂（如血糖试纸中的葡萄糖氧化酶）等。\n知识点 4 探月工程\n1.概述\n2004 年，中国探月工程立项实施，确定了“绕、落、回”三步走战略规划。\n2023 年，中国载人月球探测工程登月阶段任务启动实施，计划在________年\n前实现中国人首次登陆月球，开展月球科学考察及相关技术试验，突破掌握载人\n地月往返、月面短期驻留、人机联合探测等关键技术，完成“登、巡、采、研、"
