      "page": 115,
      "printedPage": 106,
      "group": "economy",
      "title": "经济名词",
      "text": "政政策力度和风险水平的重要指标。国际上通常将________作为赤字率的警戒线。\n狭义货币（M1）：包含流通中货币（M0）、单位活期存款、个人活期存款、\n非银行支付机构客户备付金。代表“随时能花的钱”，反映________购买力。\n广义货币（M2）：包含M1 以及单位定期和其他存款、个人存款、非存款类\n金融机构存款、非存款机构部门持有的货币市场基金份额。代表“所有的钱”，\n反映________购买力。\n知识点 8 经济效应\n挤出效应：政府通过增加支出来刺激经济时，可能会导致利率上升，从而\n________了私人投资和消费的现象。\n口红效应：因经济萧条而导致口红热卖，廉价产品在收入降低时需求量反而\n________。\n棘轮效应：人的消费习惯形成之后有________，即易于向上调整，而难于向\n下调整。\n________：强者愈强、弱者愈弱的现象，即两极分化现象。\n________：也称羊群效应，是指经济个体的从众跟风心理。\n凡勃伦效应：消费者对某些商品的需求程度，因其标价较高而________。体\n现了“炫耀性消费”的社会心理现象。\n外部效应：也称溢出效应，是指一个人或一群人的行动和决策使另一个人或\n一群人受损或受益的情况。\n【知识延伸】\n外部效应（外部性）\n正外部效应（正外部性）：某种经济活动给与这项活动无关的第三方带来的\n________。\n负外部效应（负外部性）：某种经济活动给与这项活动无关的第三方带来的\n________。"
