      "page": 121,
      "printedPage": 112,
      "group": "geography",
      "title": "气象灾害",
      "text": "知识点 5 气象灾害\n1.台风\n台风是指发生在热带或副热带洋面上的热带气旋，中心附近最大风力在 12\n级或以上。\n________区风力很小，天气晴朗。\n每年夏秋季节，我国________地区是台风登陆的主要地区。\n【知识延伸】\n热带气旋\n热带气旋，在北半球热带气旋中的气流绕中心呈________方向旋转，在南半\n球热带气旋中的气流绕中心呈________方向旋转。\n西太平洋沿岸称热带气旋为台风，大西洋称热带气旋为飓风。\n2.洪涝\n我国洪涝灾害四季都可能发生，主要发生在________季节。\n3.干旱\n在我国，干旱天气，在春夏季节分布普遍，以西北、________及东北地区为\n主。旱灾是我国发生范围________、频率最高、持续时间最长的渐发性气象灾害。\n4.沙尘暴\n主要发生在________季节，我国________地区是沙尘暴频繁发生的地区。\n5.寒潮\n确定寒潮的标准是某一地区冷空气过境后，气温 24 小时内下降________以\n上，且最低气温下降到________以下；或 48 小时内气温下降 10℃以上，且最低\n气温下降到 4℃以下；或 72 小时内气温连续下降 12℃以上，并且最低气温在 4℃\n以下。\n我国寒潮主要发生在_______，影响范围大，西北、华北及东北地区较为严重。\n知识点 6 二十四节气\n1.二十四节气的内容\n春天的节气：立春、雨水、________、春分、清明、谷雨。\n夏天的节气：立夏、小满、________、夏至、小暑、大暑。\n秋天的节气：立秋、________、白露、秋分、寒露、霜降。\n冬天的节气：立冬、小雪、大雪、________、小寒、大寒。\n节气歌：春雨惊春清谷天，夏满芒夏暑相连。秋处露秋寒霜降，冬雪雪冬小"
