      "text": "大寒。\n2.二十四节气反映的特征\n反映的特征 节气\n季节变化 立春、春分、立夏、夏至、立秋、秋分、立冬、冬至\n其中立春、立夏、立秋、立冬表示四季的________\n_______________变化 春分、夏至、秋分、冬至\n温度变化 小暑、大暑、处暑、小寒、大寒\n天气现象 雨水、谷雨、白露、寒露、霜降、小雪、大雪\n物候现象 惊蛰、________、________、________\n知识点 7 中国的邻国\n我国共有________个陆上邻国，________个隔海相望的国家。\n14 个与我国接壤的国家：朝鲜、蒙古、俄罗斯、________________、吉尔吉\n斯斯坦、塔吉克斯坦、印度、尼泊尔、不丹、阿富汗、________、缅甸、老挝、\n________。\n6 个隔海相望的国家：________、韩国、菲律宾、________、文莱、印度尼\n西亚。\n【知识延伸】\n邻国之最\n________：世界上面积最大的国家\n________________：世界上最大的内陆国\n________________：世界上最大的群岛国家，被称为“万岛之国”\n知识点 8 中国的地势与地形\n1.地势\n我国地势________，大致呈三级阶梯状分布。\n（1）第一阶梯\n平均海拔 4000 米以上，分布着________高原、________盆地。\n（2）第二阶梯\n平均海拔 1000—2000 米，分布着内蒙古高原、黄土高原、________高原、\n________盆地、准噶尔盆地、四川盆地。"
