      "title": "中国的地势与地形",
      "text": "（3）第三阶梯\n大部分海拔在 500 米以下，分布着东北平原、华北平原、长江中下游平原、\n辽东丘陵、山东丘陵、东南丘陵。\n【知识延伸】\n三级阶梯的分界线\n一、二阶梯分界线：________—祁连山脉—横断山脉\n二、三阶梯分界线：大兴安岭—________—巫山—雪峰山\n2.地形\n我国地形复杂多样，山区面积广大，占陆地总面积的三分之二。在山地中，\n镶嵌着高原、盆地、平原和丘陵等。\n四\n大\n高\n原\n______高原 世界海拔最高的高原，被称为“世界屋脊”“世界第三极”。\n______高原 称为“瀚海”，我国最平坦的高原，有典型的风蚀地貌。\n______高原 世界黄土分布最广，流水侵蚀，地表千沟万壑。\n______高原 喀斯特地貌发育典型，地势崎岖不平，有许多“坝子”。\n四\n大\n盆\n地\n______盆地 我国面积最大的盆地、最大的________。分布有塔克拉玛\n干沙漠（我国面积最大的沙漠，世界________流动沙漠）。\n______盆地 我国位置最北、纬度最高的盆地，有典型的风蚀雅丹地貌。\n柴达木盆地 我国地势________的盆地，有盐、石油、煤以及多种金属\n矿藏，被称为“________”，有风蚀雅丹地貌。\n四川盆地 我国四大盆地中地势________的盆地、我国最大的外流盆\n地，被称为“________”“紫色盆地”。\n三\n大\n平\n原\n东北平原\n我国________的平原，地跨黑、吉、辽和内蒙古四个省区，\n由三江平原、________（面积最大）、辽河平原组成。这\n是全球仅有的三大________区域之一。\n华北平原 跨越京、津、冀、鲁、豫、皖、苏 7 省市，又称黄淮海平\n原，由黄河、淮河、海河等含沙量河流合力冲积而成。\n长江中下游\n平原\n地跨鄂、湘、赣、皖、苏、浙、沪等 7 省市，湖泊密布，\n素有“________”“水乡泽国”的美誉。\n【知识延伸】\n喀斯特、雅丹、丹霞地貌\n1.喀斯特地貌：可溶性岩石（石灰岩等）被________溶蚀、侵蚀形成的地貌。\n常见于温暖湿润、降水丰富的地区。我国典型代表有________、广西________、\n贵州织金洞等。\n2.雅丹地貌：河湖相土状沉积物（泥岩、粉砂岩等）被________吹蚀、磨蚀形"
