      "text": "（5）冬小麦与春小麦的分界线：________。\n（6）旱作农业区与畜牧业区的分界线：阴山山脉。\n（7）人口地理分界线：________—腾冲线（胡焕庸线），线________居住着\n约 94%的人口；线________则地广人稀。\n（8）长江水系与黄河水系分界线：巴颜喀拉山—秦岭。\n（9）长江水系与珠江水系分界线：________。\n知识点 11 中国的自然资源\n1.土地资源\n我国土地资源的特点：（1）土地________，人均占有少。（2）________多\n于平地，耕地比例小。（3）土地资源地区________。（4）后备土地资源有限。\n（5）水土资源不平衡。\n2.水资源\n我国水资源的特点：（1）总量大，而人均水资源占有量少。（2）时空分布\n不均。________、南多北少。________、冬春少。（3）水资源与人口、耕地分布\n不匹配。中国水资源的分布情况是南多北少，而耕地的分布却是南少北多。（4）\n水环境形势严峻，地下水严重超采。\n3.能源和矿产资源\n（1）主要能源分布及其特点\n能源 分布及特点\n水能 蕴藏量居世界________。________地区分布最多。按河流统计，以\n________水系为最多，占全国的近 40%，其次是雅鲁藏布江水系。\n风能 我国风能一般________，从海边向内地迅速减弱，内陆又增强。从时\n间来说，冬春两季风力普遍大于夏秋两季。\n地热能 我国________和西藏、云南一带，是地热资源丰富地区。\n太阳能 ________日照时间及辐射量均居全国之冠。云雾、阴天特多的四川盆\n地和有“天无三日晴”之称的贵州高原是我国辐射能低值中心。\n（2）矿产资源\n我国三大化石能源（煤炭、石油、天然气）的现状是________________。\n矿产资源 分布及其特点\n煤 被誉为“工业的粮食”。我国________能源，产量居世界________，\n呈现出________的分布特点。"
