      "title": "中国的自然资源",
      "text": "石油\n我国石油资源，东部主要分布在大庆、辽河、大港、胜利、华北油\n田。西部主要分布在塔里木、柴达木、准噶尔三大盆地及吐鲁番—\n哈密盆地。\n天然气 我国天然气主要分布在中部和西部地区，其中四川盆地是我国天然\n气生产的主力地区。\n稀土\n常被称为“工业维生素”“新材料之母”等。我国是________能提\n供全部 17 种稀土元素的国家，稀土的储备量、生产量、加工能力均\n为世界________。内蒙古________稀土矿是世界最大的稀土矿。\n【知识延伸】\n全球第二大在产轻稀土矿\n2026 年 3 月 24 日，四川冕宁牦牛坪矿区新增稀土氧化物资源量 966.56 万吨，\n经权威评审备案，累计保有量达 1040.8 万吨，一跃成为全球第二大在产轻稀土矿，\n仅次于内蒙古包头白云鄂博矿。\n知识点 12 中国的少数民族\n1.民族分布特点\n我国民族分布的特点是大杂居、小聚居、交错杂居。\n2.少数民族\n（1）少数民族之“最”\n人口最多的少数民族是________，分布最广的少数民族是________，少数民\n族种类最多的省份是________省，少数民族总人口最多的省份是________省。\n（2）少数民族的节日及特色\n民族 节日 民族特色\n________ “那达慕”大会、“白节”、\n马奶节\n图腾崇拜、萨满教、腾格里汗、蒙古包，\n马头琴、长调民歌、马背民族，献“哈达”，\n安代舞\n藏族 ________ 《________________》，献“哈达”、锅庄\n舞，酥油茶、青稞酒，唐卡\n________ 古尔邦节、开斋节、圣\n纪节\n信仰伊斯兰教、不吃猪肉，男子多带小白\n帽，女子带各种花色的头巾\n苗族 苗年、跳水节 银饰、苗绣、蜡染，_______、飞歌、盘歌\n________ 肉孜节、古尔邦节、诺\n鲁孜节\n“尕巴”（四楞花帽）、阿凡提、十二木卡\n姆（大型古典音乐）、手鼓舞"
