      "text": "________ “三月三”歌节 “干栏”式建筑，《布洛陀》长诗、天琴\n________ 泼水节、关（开）门节 有“水的民族”的美称，建筑以“干栏”\n为主\n白族 三月街节、火把节 “三道茶”、崇尚白色、石雕\n彝族 彝族年、火把节 花腰刺绣\n知识点 13 中国的旅游资源\n1.重要景观\n五岳：东岳________（山东，“五岳之首”）、西岳________（陕西）、北\n岳恒山（山西）、南岳衡山（湖南）、中岳嵩山（河南）。\n四大佛教名山：山西五台山、浙江________、四川峨眉山、安徽________。\n四大道教名山：安徽齐云山、湖北________、四川青城山、江西________。\n四大石窟：甘肃敦煌________、山西大同云冈石窟、河南洛阳________、甘\n肃天水麦积山石窟。\n【知识延伸】\n四大石窟\n________：开凿时间从十六国时期至元代，以壁画和彩塑为主要表现形式。\n它是世界上现存规模最大、内容最丰富的佛教艺术地。1987 年列入世界文化遗产。\n________：北魏时期开凿，是中国第一个由皇室直接主持开凿的大型石窟群，\n被誉为“北魏皇家石窟典范”。2001 年列入世界文化遗产。\n________：开凿于北魏孝文帝年间，唐宋时期扩建，被誉为“中国石刻艺术\n的最高峰”，是中国现存窟龛最多的石窟，也是中国古碑刻最多的一处，有“古\n碑林”之称。2000 年列入世界文化遗产。\n________：始建于十六国后秦时期，后经十余个王朝的扩建和修缮，以泥塑\n艺术见长，被誉为“东方雕塑陈列馆”。2014 年列入世界文化遗产。\n四大名楼：山西鹳雀楼、江西________、湖北黄鹤楼、湖南岳阳楼。\n长江三峡：西起重庆________，东至湖北南津关，由瞿塘峡、________、西\n陵峡组成。\n________瀑布：位于贵州省，是我国最大的瀑布。\n________瀑布：位于陕西省和山西省交界处，是我国第二大瀑布，也是世界\n上最大的黄色瀑布。"
