      "page": 129,
      "printedPage": 120,
      "group": "geography",
      "title": "中国的旅游资源",
      "text": "2.世界遗产\n截至 2025 年 7 月 11 日，中国世界遗产总数达到 60 项。其中，文化遗产 41\n项，自然遗产 15 项，文化与自然双遗产 4 项。\n【知识延伸】\n西夏陵\n2025 年 7 月 11 日，联合国教科文组织第 47 届世界遗产大会通过决议，将“西\n夏陵”列入《世界遗产名录》。\n西夏陵是 11 至 13 世纪由________建立的西夏王朝的皇家陵园，位于宁夏回\n族自治区银川市西夏区贺兰山东麓，是我国现存规模最大、地面遗迹保存最为完\n整的帝王陵园之一。\n（1）世界文化与自然双遗产\n福建省________、四川峨眉山─乐山风景名胜区、安徽黄山、山东泰山（世\n界首个双重遗产）。\n（2）非物质文化遗产\n截至 2024 年年底，我国入选联合国教科文组织的非遗名录、名册的项目已达\n44 个，总数居世界第一。包括京剧、中医针灸、珠算、二十四节气、藏医药浴法、\n太极拳、送王船、中国传统制茶技艺及其相关习俗等。\n2009 年通过的端午节是我国首个入选世界非遗的节日，2024 年“春节——中\n国人庆祝传统新年的社会实践”列入人类非物质文化遗产代表作名录。\n【知识延伸】\n茶\n1.分类：绿茶、白茶、黄茶、红茶、乌龙茶、黑茶、再加工茶\n2.绿茶的制作过程：采摘→摊晾→杀青→揉捻→干燥。红茶多了发酵环节，\n黄茶多了闷黄环节，白茶少了杀青环节。\n3.茶圣：唐代陆羽，著有《茶经》（中国乃至世界现存最早、最完整、最全\n面介绍茶的第一部专著）。\n4.国际茶日：5 月 21 日。\n5.普洱茶：未经发酵的是生普洱茶（茶性较烈），发酵后的是熟普洱茶（茶\n性温和、适合日常饮用）。"
