      "text": "3.所有权\n（1）所有权的取得\n①先占：以所有人的意思占有________而取得其所有权。\n②善意取得：________他人财产的占有人，在不法将其占有的他人财产让与\n第三人后，如果受让人在取得该财产时系出于善意，即取得该财产的所有权，原\n财产所有人不得要求受让人返还。\n构成要件：出让人________；受让人受让该不动产或者动产时是________；\n以合理的价格________；应当登记的________，不需要登记的________。\n法律后果：原所有人________请求善意第三人________，善意受让人取得不\n动产或者动产的所有权，原所有权人有权向________请求赔偿损失。\n________、盗赃物、________不适用善意取得。\n③拾得遗失物：拾得遗失物应当返还权利人。拾得人应当________权利人领\n取，或者送交公安等有关部门。有关部门收到遗失物，知道权利人的，应当及时\n通知其领取；不知道的，应当及时发布招领公告。遗失物自发布________之日起\n________无人认领的，归________所有。\n（2）共有：某项财产由两个或两个以上的权利主体共有享有所有权，包括公\n民之间的共有、法人之间的共有以及公民和法人之间的共有。\n①分类\n按份共有：又称分别共有，是共有人按________对同一财产享有所有权。 共\n有人对份额，没有约定或者约定不明确的，按照________确定；不能确定出资额\n的，视为________享有。\n共同共有：又称公同共有，是基于共同关系发生的、各共有人对共有财产享\n有平等的所有权。在对外关系上，共有人享有________、承担________。\n②其他要点：如无约定，除共有人具有________、________、________外，\n视为按份共有。 一方转让份额，共有人享有优先购买权。\n4.担保物权\n（1）抵押权\n①含义：抵押权，是指债权人对于债务人或者第三人________占有而提供担\n保的财产，于债务人不履行债务或发生当事人约定的实现抵押权的情形时，依法\n享有的就该财产________的权利。\n②不能设立抵押的财产：土地________；宅基地、自留地、自留山等集体所\n有土地的________，但是法律规定可以抵押的除外；学校、幼儿园、医疗机构等\n为公益目的成立的非营利法人的教育设施、医疗卫生设施和其他________；所有\n权、使用权不明或者有争议的财产；依法被________、________、监管的财产；"
