      "title": "物权",
      "text": "法律、行政法规规定不得抵押的其他财产。\n③抵押权的设立：设立抵押权，当事人应当以________形式订立抵押合同。\n以不动产抵押，应当办理抵押物登记，抵押权自________设立。以动产抵押的，\n抵押权自________生效时设立；未经登记，不得对抗善意第三人。以动产抵押的，\n不得对抗正常经营活动中已经支付合理价款并取得抵押财产的买受人。\n（2）质押权\n①含义：质权，是指为了担保债务的履行，债务人或者第三人将其动产或者\n权利________债权人占有，当债务人不履行债务时，债权人有就其占有的财产优\n先受偿的权利。\n②设立：________质押合同；动产质权自出质人________质押财产时设立，\n权利质权自权利凭证交付或办理出质________时设立。\n（3）留置权\n债权人按合同约定占有债务人的财产，债权________，在债务人逾期不履行\n债务时，有留置该财产以迫使债务人履行债务，并在债务人仍不履行债务时就该\n财产优先受偿的权利。它是________，权利人不得擅自使用、出租、处分留置物。\n【知识链接】其他担保方式\n1.定金：合同当事人为确保合同的履行，依据法律规定或者当事人双方的约\n定，由当事人一方在合同订立时或订立后、履行前，按合同标的额的一定比例，\n预先给付对方当事人的金钱或其他代替物。定金与违约金________同时适用。\n①定金的数额：由当事人________，但不得超过主合同标的额的________，\n超过部分________定金的效力。\n②定金罚则：债务人履行债务的，定金应当抵作价款或者收回。________定\n金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，无权\n请求________；________定金的一方不履行债务或者履行债务不符合约定，致使\n不能实现合同目的的，应当________返还定金。\n2.保证\n①不得为保证人：________，除经国务院批准为外国政府和国际经济组织贷\n款进行转贷外，不得为保证人；________、________、医院等以公益为目的的事\n业单位、社会团体，不得为保证人。\n②保证方式：分为________和__________两种，保证人和债权人应当在保证\n合同中约定保证的方式。"
