      "group": "law",
      "title": "债权",
      "text": "知识点 5 债权\n1.债：特定当事人之间得请求为特定行为的民事法律关系。享有权利的人是\n债权人，负有义务的人是债务人。\n（1）债权和物权区别：\n①________不同：物权是绝对权；债权是相对权，义务主体是特定的债务人。\n②________不同：物权以物为客体，这里所说的物，是指人身之外，为人力\n所能支配，并且有一定使用价值的物质资料，行为和精神产品均不能作为物权的\n客体。\n（2）产生：债的发生根据是引起债的法律关系发生的事实。主要有：不当得\n利、无因管理、合同、侵权行为。\n2.不当得利：没有合法根据，使他人受到损失而自己获得利益的事实。\n（1）构成要件：一方________；他方________；获得利益和受到损失之间有\n因果关系；获得利益________合法根据。\n（2）不成立不当得利的情形：为履行________进行的给付；债务________的\n清偿；明知无给付义务而进行的债务清偿。\n（3）不当得利的法律效力\n①受益人的返还义务：不当得利成立后，受害人有权请求受益人返还不当得\n利，受益人负有返还不当得利的义务。\n②第三人的返还义务：得利人已经将取得的利益________给第三人的，受损\n失的人可以请求第三人在________承担返还义务。\n3.无因管理：没有法定或约定的义务，为避免他人利益受损，自愿管理他人\n事务的行为。管理他人事务的人，为管理人；事务被他人管理的人，为本人。\n（1）构成要件：没有法定或约定的________；有__________益的意思；为他\n人管理事务；符合受益人________。\n（2）无因管理之债：管理人有权要求本人偿还因管理事务所支出的________；\n管理人可以请求受益人对其因管理受到的损失给予适当________。\n知识点 6 结婚与离婚\n1.结婚条件\n（1）实质条件\n①应当男女双方________。"
