      "page": 163,
      "printedPage": 154,
      "group": "law",
      "title": "公民的基本权利和义务",
      "text": "可以依照法律规定对公民的私有财产实行征收或者征用并给予________。\n（8）文化教育：公民受教育的权利和________；从事科学研究、文艺创作的\n权利。\n2.公民的基本义务\n（1）维护国家的统一和各民族的团结。\n（2）遵守宪法和法律，保守国家秘密，爱护公共财产，遵守劳动纪律，遵守\n公共秩序，尊重社会公德。\n（3）维护祖国的安全、荣誉和利益。\n（4）保卫祖国、抵抗侵略，依法服兵役和参加民兵组织。\n（5）依法纳税。\n知识点 5 选举制度\n1.选举权\n（1）条件：年满 18 周岁；中华人民共和国公民；未被剥夺政治权利。\n（2）选举方式：直接选举与间接选举相结合。\n①直接选举：由选民投票选举代表。不设区的市、市辖区、县、自治县、乡、\n民族乡、镇的人大代表由选民直接选举，也即________以下（含县级）为直接选\n举。\n②间接选举：________人民代表大会和省、自治区、直辖市、________、自\n治州的人民代表大会代表由下一级人民代表大会选举。\n（3）选举组织\n①间接选举：________组织。\n②直接选举：选举委员会组织根据居住状况、生产单位、事业单位、工作单\n位进行选区划分。\n（4）投票选举\n①在直接选举中，________的选民参加投票有效；代表候选人获得参加投票\n的选民________即可当选。\n②在间接选举中，代表候选人须获得全体代表的________选票才能当选。\n2.选举权的平等性原则：2010 年修改选举法实现________。\n3.________投票的原则"
