      "topic": "考古文化遗址",
      "question": "7.二里头文化：位于河南省洛阳市偃师二里头，学术界一般认为它是夏王朝中晚期都城。拥有目前已知我国最早的城市道路系统、宫室建筑群和宫城、最早的青铜礼器群、以青铜冶铸作坊和绿松石器制造作坊为代表的最早的官营作坊区等诸多重要遗存。二里头遗址是迄今为止可确认的中国最早的王朝都城遗址，开中国古代都邑制度之先河，一般将其称为“______”。",
      "answer": "7.二里头文化：位于河南省洛阳市偃师二里头，学术界一般认为它是夏王朝中晚期都城。拥有目前已知我国最早的城市道路系统、宫室建筑群和宫城、最早的青铜礼器群、以青铜冶铸作坊和绿松石器制造作坊为代表的最早的官营作坊区等诸多重要遗存。二里头遗址是迄今为止可确认的中国最早的王朝都城遗址，开中国古代都邑制度之先河，一般将其称为“最早的中国”。",
