      "question": "8.殷墟遗址：位于河南省安阳市，商代后期都城遗址。出土了大量______，这是中国最早的系统文字。出土文物中的______，是中国现存最大、最重的青铜器。这是中国历史上第一个______、并为考古发掘所证实的都城遗址。",
      "answer": "8.殷墟遗址：位于河南省安阳市，商代后期都城遗址。出土了大量甲骨文，这是中国最早的系统文字。出土文物中的后母戊鼎，是中国现存最大、最重的青铜器。这是中国历史上第一个有文献可考、并为考古发掘所证实的都城遗址。",
