      "title": "古代赋税制度",
      "topic": "古代赋税制度",
      "question": "3.两税法：______后期，改革赋税制度，实施两税法。两税法将各种名目的赋税统一并到______中；每户按资产交纳户税，按田亩交纳地税；分为______两季征收。两税法改变了以往“以人丁为主”的征税标准，转向“以财产、土地为核心”。",
      "answer": "3.两税法：唐朝后期，改革赋税制度，实施两税法。两税法将各种名目的赋税统一并到户税和地税中；每户按资产交纳户税，按田亩交纳地税；分为夏秋两季征收。两税法改变了以往“以人丁为主”的征税标准，转向“以财产、土地为核心”。",
