      "answer": "2.李悝变法：战国初期，魏文侯为了增强国力，任用李悝为相，在诸侯国中率先推行变法。主要内容有打破贵族世袭的“世卿世禄制”，主张选贤任能；推行“尽地力之教”；实施“平籴法”；编撰《法经》（中国历史上第一部系统的成文法典）。这是中国历史上第一次比较系统的地主阶级改革。",
