      "question": "宋元时期，对外交流的重心从陆路转向海路，______进入鼎盛时期。中国的四大发明（造纸术、印刷术、指南针、火药）通过阿拉伯商人等渠道大规模西传，对世界文明进程产生了革命性影响。",
