      "title": "古代农业发展 · 历史地位",
      "topic": "古代农业发展",
      "question": "（4）隋唐时期：______时期，吴王夫差开凿了连接长江与淮河的邗沟，这是有确切纪年的中国大运河最早的河段。隋朝时期，为加强都城洛阳与南方的联系，隋炀帝下令大规模开凿运河。元朝时期，为缩短航程，对运河进行了“______”，先后开凿了济州河、会通河、通惠河等新河道，使运河不再绕道洛阳。",
      "answer": "（4）隋唐时期：春秋时期，吴王夫差开凿了连接长江与淮河的邗沟，这是有确切纪年的中国大运河最早的河段。隋朝时期，为加强都城洛阳与南方的联系，隋炀帝下令大规模开凿运河。元朝时期，为缩短航程，对运河进行了“裁弯取直”，先后开凿了济州河、会通河、通惠河等新河道，使运河不再绕道洛阳。",
