      "answer": "中共一大：1921年7月23日，中共一大在上海（后转移至浙江嘉兴南湖）召开。会议确定党的名称为“中国共产党”，通过了党的第一个纲领，选举陈独秀为中央局书记。党的一大的召开标志着中国共产党的成立。",
