      "question": "中华苏维埃共和国成立：1931年11月，中华苏维埃第一次全国代表大会在江西______召开，宣布成立中华苏维埃共和国临时中央政府，毛泽东当选为主席。这是中国共产党领导建立的第一个全国性红色政权。",
      "answer": "中华苏维埃共和国成立：1931年11月，中华苏维埃第一次全国代表大会在江西瑞金召开，宣布成立中华苏维埃共和国临时中央政府，毛泽东当选为主席。这是中国共产党领导建立的第一个全国性红色政权。",
