      "volume": "文史常识",
      "category": "常识判断",
      "title": "土地革命",
      "topic": "土地革命",
      "question": "红军长征：王明等人的______错误，使红军在第五次反“围剿”中遭到失败，被迫开始长征。1934年10月10日，红军从江西省瑞金、古城等地出发。1936年10月9日，红四方面军指挥部到达______，同红一方面军会师；10月22日，红二方面军指挥部到达甘肃隆德将台堡（今属宁夏回族自治区），同红一方面军胜利会师。红军三大主力会师，宣告红军二万五千里长征胜利结束。",
      "answer": "红军长征：王明等人的“左”倾机会主义错误，使红军在第五次反“围剿”中遭到失败，被迫开始长征。1934年10月10日，红军从江西省瑞金、古城等地出发。1936年10月9日，红四方面军指挥部到达甘肃会宁，同红一方面军会师；10月22日，红二方面军指挥部到达甘肃隆德将台堡（今属宁夏回族自治区），同红一方面军胜利会师。红军三大主力会师，宣告红军二万五千里长征胜利结束。",
      "digestTerms": [
        "“左”倾机会主义",
        "甘肃会宁"
      ],
      "digestChecklist": true,
      "studyLabel": "常识消化清单",
