      "topic": "唐宋八大家",
      "question": "古文运动古文运动是唐宋时期提倡古文、反对骈文的文体改革运动。其核心是反对六朝以来形式僵化、内容空洞的骈文，提倡恢复先秦两汉时期质朴自由、言之有物的散文传统，以复兴______，挽救时局。",
      "answer": "古文运动古文运动是唐宋时期提倡古文、反对骈文的文体改革运动。其核心是反对六朝以来形式僵化、内容空洞的骈文，提倡恢复先秦两汉时期质朴自由、言之有物的散文传统，以复兴儒学，挽救时局。",
