      "answer": "辛弃疾：别号稼轩，人称“词中之龙”，南宋爱国词人。与苏轼并称“苏辛”，与李清照并称“济南二安”。在文学史上第一次把金戈铁马的铿锵之声带入词，代表作是《鹧鸪天》《水龙吟》《青玉案·元夕》《菩萨蛮》和作品集《稼轩长短句》等。",
