      "question": "《红楼梦》：作者清代曹雪芹，原名《______》《风月宝鉴》《金陵十二钗》等，成书于乾隆年间，被誉为“封建社会的百科全书”，中国最具文学成就的古典小说及章回小说的______。《红楼梦》第一回中写到“满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味？”“字字看来皆是血，______不寻常”出自曹雪芹的《回前诗》，是曹雪芹自己对《红楼梦》的评说。",
      "answer": "《红楼梦》：作者清代曹雪芹，原名《石头记》《风月宝鉴》《金陵十二钗》等，成书于乾隆年间，被誉为“封建社会的百科全书”，中国最具文学成就的古典小说及章回小说的巅峰之作。《红楼梦》第一回中写到“满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味？”“字字看来皆是血，十年辛苦不寻常”出自曹雪芹的《回前诗》，是曹雪芹自己对《红楼梦》的评说。",
