      "title": "非金属物质 · 氧（O）",
      "topic": "非金属物质",
      "question": "臭氧（O3）：常温常压下，是一种具有特殊鱼腥味的______气体。液态时呈深蓝色，固态时呈紫黑色。具有极强的______，可用于饮用水杀菌、游泳池消毒、空气净化、纺织品的漂白等。雷雨过后空气格外清新，就是因为雷电使部分氧气转化为了低浓度的臭氧。主要存在于臭氧层中，可吸收______，因此臭氧层被称为“地球生命的保护伞”。",
      "answer": "臭氧（O3）：常温常压下，是一种具有特殊鱼腥味的淡蓝色气体。液态时呈深蓝色，固态时呈紫黑色。具有极强的氧化性，可用于饮用水杀菌、游泳池消毒、空气净化、纺织品的漂白等。雷雨过后空气格外清新，就是因为雷电使部分氧气转化为了低浓度的臭氧。主要存在于臭氧层中，可吸收紫外线，因此臭氧层被称为“地球生命的保护伞”。",
      "digestTerms": [
        "淡蓝色",
        "氧化性",
        "紫外线"
      ],
      "digestChecklist": true,
      "studyLabel": "常识消化清单",
