      "title": "金属物质 · 铁（Fe）",
      "topic": "金属物质",
      "question": "根据______的不同，铁合金主要分为生铁和钢两类。生铁的含碳量为2.11%至4.3%，硬度大、抗压，但性脆、缺乏韧性，常用于铸造机床床身、管道等。钢的含碳量为0.02%至2.11%，具有良好的延展性、韧性和机械性能，广泛用于建筑、机械、交通、日用品等几乎所有领域，是______、用途最广的合金。",
      "answer": "根据含碳量的不同，铁合金主要分为生铁和钢两类。生铁的含碳量为2.11%至4.3%，硬度大、抗压，但性脆、缺乏韧性，常用于铸造机床床身、管道等。钢的含碳量为0.02%至2.11%，具有良好的延展性、韧性和机械性能，广泛用于建筑、机械、交通、日用品等几乎所有领域，是用量最大、用途最广的合金。",
