      "topic": "有机化合物",
      "question": "乙酸乙酯酒的芳香气味来自______。新制的酒存放期间，酒里的醛不断氧化为羧酸，而羧酸再和酒精发生酯化反应，生成具有芳香气味的乙酸乙酯。时间越久，就有越多的乙酸乙酯生成，因此酒越陈越香。",
      "answer": "乙酸乙酯酒的芳香气味来自乙酸乙酯。新制的酒存放期间，酒里的醛不断氧化为羧酸，而羧酸再和酒精发生酯化反应，生成具有芳香气味的乙酸乙酯。时间越久，就有越多的乙酸乙酯生成，因此酒越陈越香。",
