      "question": "（3）分类脱氧核糖核酸（DNA）：呈______结构，携带有合成RNA和蛋白质所必需的遗传信息，引导生物发育与生命机能运作。DNA是______遗传物质，是遗传信息的载体，绝大部分生物的遗传物质为DNA。带有遗传信息的DNA片段称为______，一个DNA分子上有很多个基因。",
      "answer": "（3）分类脱氧核糖核酸（DNA）：呈双螺旋结构，携带有合成RNA和蛋白质所必需的遗传信息，引导生物发育与生命机能运作。DNA是主要的遗传物质，是遗传信息的载体，绝大部分生物的遗传物质为DNA。带有遗传信息的DNA片段称为基因，一个DNA分子上有很多个基因。",
