      "topic": "人体系统",
      "question": "（1）胰岛素：由胰腺内胰岛β细胞分泌，在调节人体血糖水平方面起着至关重要的作用，是人体内唯一降低______的激素。分泌不足会造成______，分泌过多会引起低血糖。外源性胰岛素主要用于糖尿病治疗，采用______（腹部、大腿、上臂、臀部）方式。",
      "answer": "（1）胰岛素：由胰腺内胰岛β细胞分泌，在调节人体血糖水平方面起着至关重要的作用，是人体内唯一降低血糖的激素。分泌不足会造成糖尿病，分泌过多会引起低血糖。外源性胰岛素主要用于糖尿病治疗，采用皮下注射（腹部、大腿、上臂、臀部）方式。",
