      "topic": "人体系统",
      "question": "（2）甲状腺素：由甲状腺合成和分泌，能促进体内物质和能量代谢，促进身体和智力发育，对骨骼、神经系统和生殖系统有显著影响，其合成需要______。",
      "answer": "（2）甲状腺素：由甲状腺合成和分泌，能促进体内物质和能量代谢，促进身体和智力发育，对骨骼、神经系统和生殖系统有显著影响，其合成需要碘元素。",
