      "answer": "（4）肾上腺素：由肾上腺分泌，在人体应对紧急情况、调节生理功能方面发挥着“急救兵”般的核心作用。当人经历某些刺激（如兴奋、恐惧、紧张等）时，会分泌肾上腺素，让人呼吸加快，心跳与血液流动加速，瞳孔放大，为身体活动提供更多能量，使反应更加快速。",
