      "answer": "对于1岁以上儿童及成人，发生重度气道梗阻且意识清醒时，先进行5次背部拍击，即用掌根在患者两侧肩胛骨连线的中点处，快速、有力地连续拍击5次。如果拍背后异物未排出，立即转为腹部冲击。交替进行“5次背部拍击”和“5次腹部冲击”，直到异物排出或患者失去意识。",
