      "question": "④空调制冷时，将出风口______吹，冷气会自然下沉，房间凉得更快且更均匀。空调制热时，将出风口______吹，先将地板和人体脚部区域加热，然后热空气自然上升，使整个房间温暖得更快、更舒适。",
      "answer": "④空调制冷时，将出风口向上吹，冷气会自然下沉，房间凉得更快且更均匀。空调制热时，将出风口向下吹，先将地板和人体脚部区域加热，然后热空气自然上升，使整个房间温暖得更快、更舒适。",
