      "question": "5.地震若身处低矮楼层，应尽快疏散到屋外开阔空地，远离人多的地方、高层建筑和桥梁。若身处高层，应躲在低矮牢固的家具（如床、桌）下或______、刚度强的小开间的室内（如厨房、卫生间、承重墙墙角等）暂避，并用手护住头部。",
      "answer": "5.地震若身处低矮楼层，应尽快疏散到屋外开阔空地，远离人多的地方、高层建筑和桥梁。若身处高层，应躲在低矮牢固的家具（如床、桌）下或跨度小、刚度强的小开间的室内（如厨房、卫生间、承重墙墙角等）暂避，并用手护住头部。",
