      "question": "世界有三大地震带，即______地震带（世界上最大的地震带）、欧亚地震带、海岭地震带。其中环太平洋地震带主要影响我国东部地区，欧亚地震带主要影响我国西南地区，海岭地震带不影响我国。",
      "answer": "世界有三大地震带，即环太平洋地震带（世界上最大的地震带）、欧亚地震带、海岭地震带。其中环太平洋地震带主要影响我国东部地区，欧亚地震带主要影响我国西南地区，海岭地震带不影响我国。",
