      "topic": "灾害应对",
      "question": "（3）震级：衡量地震本身大小，代表地震释放能量的多少。一次地震，______震级。我国目前使用的震级标准是里氏分级表，共分9个等级，震级相差一级，地震所释放的能量相差______倍。",
      "answer": "（3）震级：衡量地震本身大小，代表地震释放能量的多少。一次地震，只有一个震级。我国目前使用的震级标准是里氏分级表，共分9个等级，震级相差一级，地震所释放的能量相差30倍。",
