      "question": "（5）地震波纵波（P波）：振动方向与传播方向一致。会引起地面上下颠簸，破坏力相对较弱。传播速度______，穿透力最强，可以在固体、液体和气体中传播。",
      "answer": "（5）地震波纵波（P波）：振动方向与传播方向一致。会引起地面上下颠簸，破坏力相对较弱。传播速度最快，穿透力最强，可以在固体、液体和气体中传播。",
