      "question": "横波（S波）：振动方向与传播方向垂直。会引起地面水平摇晃，对建筑物的剪切破坏力强。传播速度较慢，只能在______中传播，不能在液体和气体中传播。",
      "answer": "横波（S波）：振动方向与传播方向垂直。会引起地面水平摇晃，对建筑物的剪切破坏力强。传播速度较慢，只能在固体中传播，不能在液体和气体中传播。",
