      "answer": "（4）生物质能生物质能是太阳能以化学能形式贮存在生物质中的能量形式，即以生物质为载体的能量，如沼气（主要成分为甲烷）。生物质能是唯一一种可再生的碳源，也是人类历史上最早使用的能源。",
