      "question": "2020年7月23日，“天问一号”在______卫星发射中心由“长征五号遥四”运载火箭发射成功。此次任务是“长征五号”系列运载火箭首次应用性发射，也是中国运载火箭首次执行地球—火星转移轨道发射任务。“天问一号”任务的顺利完成标志着我国成为世界上______一次性完成火星“绕、着、巡”的国家。",
