      "topic": "通货膨胀",
      "question": "1.通货膨胀的含义通货膨胀是指在货币流通条件下，因货币供给______货币实际需求，导致货币贬值，而引起的一段时间内商品和劳务的价格持续而普遍地______现象。",
      "answer": "1.通货膨胀的含义通货膨胀是指在货币流通条件下，因货币供给大于货币实际需求，导致货币贬值，而引起的一段时间内商品和劳务的价格持续而普遍地上涨现象。",
