      "question": "按国际惯例，当CPI增幅连续超过______时，就意味着发生了通货膨胀；当CPI增幅低于1%且持续一段时间，预示着通货紧缩的风险。",
      "answer": "按国际惯例，当CPI增幅连续超过3%时，就意味着发生了通货膨胀；当CPI增幅低于1%且持续一段时间，预示着通货紧缩的风险。",
