      "question": "4.通货膨胀与失业的关系菲利普斯曲线反映了失业率和通货膨胀率之间______变动的关系。即通货膨胀率高，失业率低；通货膨胀率低，则失业率高。",
      "answer": "4.通货膨胀与失业的关系菲利普斯曲线反映了失业率和通货膨胀率之间反向变动的关系。即通货膨胀率高，失业率低；通货膨胀率低，则失业率高。",
