      "topic": "宏观经济政策",
      "question": "货币政策是指______通过控制和调节货币供应量以保持社会总供给和社会总需求平衡的一种经济政策。主要工具包括法定存款准备金率、______、公开市场业务、______。",
      "answer": "货币政策是指中央银行通过控制和调节货币供应量以保持社会总供给和社会总需求平衡的一种经济政策。主要工具包括法定存款准备金率、再贴现率、公开市场业务、基准利率。",
