      "title": "经济名词",
      "topic": "经济名词",
      "question": "公共物品：满足社会公众需要的商品。一般具有两大特征：（1）______：消费者对某种物品的消费并不会影响其他人对该物品的消费。（2）______：消费者对某种物品的消费并不会阻止其他人对该物品的消费。",
      "answer": "公共物品：满足社会公众需要的商品。一般具有两大特征：（1）非竞争性：消费者对某种物品的消费并不会影响其他人对该物品的消费。（2）非排他性：消费者对某种物品的消费并不会阻止其他人对该物品的消费。",
