      "question": "恩格尔系数：表示______总额占个人消费支出总额的比重。通常将其作为衡量家庭或国家______的指标，恩格尔系数越大，一个国家或家庭生活越______；反之，恩格尔系数越小，生活越______。",
      "answer": "恩格尔系数：表示食品支出总额占个人消费支出总额的比重。通常将其作为衡量家庭或国家富裕程度的指标，恩格尔系数越大，一个国家或家庭生活越贫困；反之，恩格尔系数越小，生活越富裕。",
