      "question": "2.地形雨当潮湿的气团前进时，遇到高山阻挡，气流被迫缓慢上升，引起绝热降温，发生凝结而形成的降水。地形雨多降在______面的山坡（______坡）上，背风坡面则因空气下沉引起绝热增温，反使云量消减，降雨减少。",
