      "topic": "降水的类型",
      "question": "梅雨梅雨，是在每年______的东南季风带来的太平洋暖湿气流，经过中国长江中下游地区、中国台湾地区、日本中南部以及韩国南部等地出现的持续天阴有雨的气候现象。由于正是江南梅子的成熟期，故称其为“梅雨”。",
      "answer": "梅雨梅雨，是在每年6、7月份的东南季风带来的太平洋暖湿气流，经过中国长江中下游地区、中国台湾地区、日本中南部以及韩国南部等地出现的持续天阴有雨的气候现象。由于正是江南梅子的成熟期，故称其为“梅雨”。",
