      "answer": "4.台风雨台风雨是由热带气旋（台风或飓风）带来的降水。降水主要集中在台风眼周围的“云墙区”，这里上升气流最强，降雨最猛烈；而台风眼内部气流下沉，通常是晴朗无风的。主要影响热带、亚热带沿海地区，多发生在夏秋季节。",
