      "volume": "法律常识",
      "category": "常识判断",
      "title": "物权 · 所有权 · 所有权的取得",
      "topic": "物权",
      "question": "②善意取得：______他人财产的占有人，在不法将其占有的他人财产让与第三人后，如果受让人在取得该财产时系出于善意，即取得该财产的所有权，原财产所有人不得要求受让人返还。",
      "answer": "②善意取得：无权处分他人财产的占有人，在不法将其占有的他人财产让与第三人后，如果受让人在取得该财产时系出于善意，即取得该财产的所有权，原财产所有人不得要求受让人返还。",
