      "question": "构成要件：出让人______；受让人受让该不动产或者动产时是______；以合理的价格______；应当登记的______，不需要登记的______。",
      "answer": "构成要件：出让人无处分权；受让人受让该不动产或者动产时是善意的；以合理的价格转让；应当登记的已登记，不需要登记的已交付。",
