      "question": "法律后果：原所有人______请求善意第三人______，善意受让人取得不动产或者动产的所有权，原所有权人有权向______请求赔偿损失。",
      "answer": "法律后果：原所有人无权请求善意第三人返还原物，善意受让人取得不动产或者动产的所有权，原所有权人有权向无处分权人请求赔偿损失。",
