      "volume": "法律常识",
      "category": "常识判断",
      "title": "物权 · 担保物权 · 抵押权",
      "topic": "物权",
      "question": "以不动产抵押，应当办理抵押物登记，抵押权自______设立。以动产抵押的，抵押权自______生效时设立；未经登记，不得对抗善意第三人。以动产抵押的，不得对抗正常经营活动中已经支付合理价款并取得抵押财产的买受人。",
      "answer": "以不动产抵押，应当办理抵押物登记，抵押权自登记时设立。以动产抵押的，抵押权自抵押合同生效时设立；未经登记，不得对抗善意第三人。以动产抵押的，不得对抗正常经营活动中已经支付合理价款并取得抵押财产的买受人。",
