      "volume": "法律常识",
      "category": "常识判断",
      "title": "物权 · 担保物权 · 质押权",
      "topic": "物权",
      "question": "②设立：______质押合同；动产质权自出质人______质押财产时设立，权利质权自权利凭证交付或办理出质______时设立。",
      "answer": "②设立：书面质押合同；动产质权自出质人交付质押财产时设立，权利质权自权利凭证交付或办理出质登记时设立。",
