      "topic": "物权",
      "question": "1.定金：合同当事人为确保合同的履行，依据法律规定或者当事人双方的约定，由当事人一方在合同订立时或订立后、履行前，按合同标的额的一定比例，预先给付对方当事人的金钱或其他代替物。定金与违约金______同时适用。",
      "answer": "1.定金：合同当事人为确保合同的履行，依据法律规定或者当事人双方的约定，由当事人一方在合同订立时或订立后、履行前，按合同标的额的一定比例，预先给付对方当事人的金钱或其他代替物。定金与违约金不得同时适用。",
