      "question": "②定金罚则：债务人履行债务的，定金应当抵作价款或者收回。______定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，无权请求______；______定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，应当______返还定金。",
      "answer": "②定金罚则：债务人履行债务的，定金应当抵作价款或者收回。给付定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，无权请求返还定金；收受定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，应当双倍返还定金。",
