      "question": "3.协议离婚：协议离婚要经过______冷静期。自婚姻登记机关收到离婚登记申请之日起______，任何一方不愿意离婚的，可以向婚姻登记机关撤回离婚登记申请。该期限届满后______，双方应当亲自到婚姻登记机关申请发给离婚证；未申请的，视为______离婚登记申请。",
      "answer": "3.协议离婚：协议离婚要经过30天冷静期。自婚姻登记机关收到离婚登记申请之日起30日内，任何一方不愿意离婚的，可以向婚姻登记机关撤回离婚登记申请。该期限届满后30日内，双方应当亲自到婚姻登记机关申请发给离婚证；未申请的，视为撤回离婚登记申请。",
