      "question": "（1）代位继承代位继承，是指在______中，被继承人的子女______被继承人死亡或宣告死亡时，本应由继承人继承的遗产，由被继承人的子女的______血亲代位继承；被继承人的兄弟姐妹先于被继承人死亡的，由被继承人的兄弟姐妹的______代位继承的法律制度。",
      "answer": "（1）代位继承代位继承，是指在法定继承中，被继承人的子女先于被继承人死亡或宣告死亡时，本应由继承人继承的遗产，由被继承人的子女的直系晚辈血亲代位继承；被继承人的兄弟姐妹先于被继承人死亡的，由被继承人的兄弟姐妹的子女代位继承的法律制度。",
