      "topic": "侵权责任",
      "question": "（1）无民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间受到人身损害的，______、______或者其他教育机构应当承担责任，但能够证明尽到教育、管理职责的，不承担责任。此时教育机构承担______责任。",
      "answer": "（1）无民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间受到人身损害的，幼儿园、学校或者其他教育机构应当承担责任，但能够证明尽到教育、管理职责的，不承担责任。此时教育机构承担过错推定责任。",
