      "topic": "侵权责任",
      "question": "（2）建筑物、构筑物或者其他设施倒塌造成他人损害的，由建设单位与施工单位承担______，但是建设单位与施工单位能够证明不存在质量缺陷的除外。",
      "answer": "（2）建筑物、构筑物或者其他设施倒塌造成他人损害的，由建设单位与施工单位承担连带责任，但是建设单位与施工单位能够证明不存在质量缺陷的除外。",
      "digestTerms": [
        "连带责任"
      ],
      "digestChecklist": true,
      "studyLabel": "常识消化清单",
      "digestPage": 138,
