      "volume": "法律常识",
      "category": "常识判断",
      "title": "侵权责任 · 物件损害责任",
      "topic": "侵权责任",
      "question": "（3）从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害，由______依法承担侵权责任；经调查难以确定具体侵权人的，除能够证明自己不是侵权人的外，由______的建筑物使用人给予______。可能加害的建筑物使用人补偿后，有权向侵权人追偿。______等建筑物管理人未采取必要的安全保障措施的，应当依法承担未履行安全保障义务的侵权责任。",
      "answer": "（3）从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害，由侵权人依法承担侵权责任；经调查难以确定具体侵权人的，除能够证明自己不是侵权人的外，由可能加害的建筑物使用人给予补偿。可能加害的建筑物使用人补偿后，有权向侵权人追偿。物业服务企业等建筑物管理人未采取必要的安全保障措施的，应当依法承担未履行安全保障义务的侵权责任。",
