      "question": "（5）在公共场所或者道路上挖掘、修缮安装地下设施等造成他人损害，施工人______已经设置明显标志和采取安全措施的，应当承担侵权责任。窨井等地下设施造成他人损害，管理人不能证明尽到管理职责的，应当承担侵权责任。",
      "answer": "（5）在公共场所或者道路上挖掘、修缮安装地下设施等造成他人损害，施工人不能证明已经设置明显标志和采取安全措施的，应当承担侵权责任。窨井等地下设施造成他人损害，管理人不能证明尽到管理职责的，应当承担侵权责任。",
