      "topic": "量刑",
      "question": "（1）一般累犯：被判处______徒刑以上刑罚的犯罪分子，刑罚______或者赦免以后，在______再犯应当判处______徒刑以上刑罚之罪的犯罪分子。",
      "answer": "（1）一般累犯：被判处有期徒刑以上刑罚的犯罪分子，刑罚执行完毕或者赦免以后，在5年内再犯应当判处有期徒刑以上刑罚之罪的犯罪分子。",
