      "question": "2.自首自首，是指犯罪以后______，如实供述自己罪行的行为，或者被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪行的行为。对于自首的犯罪分子，可以______或者______处罚。其中，犯罪较轻的，可以免除处罚。",
      "answer": "2.自首自首，是指犯罪以后自动投案，如实供述自己罪行的行为，或者被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪行的行为。对于自首的犯罪分子，可以从轻或者减轻处罚。其中，犯罪较轻的，可以免除处罚。",
