      "answer": "①国家工作人员：在国家机关中从事公务的人员；国有公司、企业、事业单位、人民团体中从事公务的人员；国家机关、国有公司、企业、事业单位委派到非国有公司、企业、事业单位、社会团体从事公务的人员；村委会等村基层组织人员协助政府从事七类行政管理工作，属于“其他依照法律从事公务的人员”（人大关于《刑法》第93条第2款的立法解释）。",
