      "title": "法的规范作用",
      "topic": "法的规范作用",
      "question": "法的规范作用：口诀释义作用对象教（教）教育作用：通过法的实施，法律规范对人们今后的行为发生直接或间接的诱导影响______的行为预（育）预测作用：根据法律规定，人们可以预先估计到他们相互间将如何行为人们相互间的行为引（尹）指引作用：法作为行为规范，为人们提供某种行为模式，指引人们可以这样行为、必须这样行为或不得这样行为，从而对行为者本人的行为产生影响每个人______的行为制（志）强制作用：法为保障自己得以充分实现，运用国家强制力制裁、惩罚违法行为。法的强制作用是法的其他作用的保证______的违法犯罪行为评（平）评价作用：法作为一种社会规范具有判断、衡量他人行为是否合法或有效的作用______的行为",
      "answer": "法的规范作用：口诀释义作用对象教（教）教育作用：通过法的实施，法律规范对人们今后的行为发生直接或间接的诱导影响一般人的行为预（育）预测作用：根据法律规定，人们可以预先估计到他们相互间将如何行为人们相互间的行为引（尹）指引作用：法作为行为规范，为人们提供某种行为模式，指引人们可以这样行为、必须这样行为或不得这样行为，从而对行为者本人的行为产生影响每个人自己的行为制（志）强制作用：法为保障自己得以充分实现，运用国家强制力制裁、惩罚违法行为。法的强制作用是法的其他作用的保证违法犯罪者的违法犯罪行为评（平）评价作用：法作为一种社会规范具有判断、衡量他人行为是否合法或有效的作用他人的行为",
